<script setup lang="ts">
import {ref,computed,watch,defineAsyncComponent} from 'vue'
import {useStudio,state,states,id} from '../studioContext'
import {profile} from '../people'
import EntityActions from '../EntityActions.vue'
import ReviewUnit from '../ReviewUnit.vue'
import ReviewBadge from '../ReviewBadge.vue'
import AppIcon from '../AppIcon.vue'
import Portrait from '../Portrait.vue'
import PersonaEditor from '../PersonaEditor.vue'
import RegionPicker from '../RegionPicker.vue'
const ClueGraph=defineAsyncComponent(()=>import('../ClueGraph.vue'))
const s=useStudio(),selected=ref(''),showFace=ref(false)
const people=computed(()=>s.entries('character')),r=computed(()=>people.value.find((r:any)=>r.id===selected.value)||people.value[0]),knowledge=computed(()=>r.value?s.rec('knowledge',r.value.id):null)
const structuredFacts=computed(()=>s.rec('material','main')?.draft.structured?.statements.filter((v:any)=>v.personId===r.value?.id&&!v.profileField)||[])
const clues=computed(()=>s.entries('clue').filter((r:any)=>r.state==='confirmed'&&r.published))
const knowledgeWaiting=computed(()=>knowledge.value?.published===null&&knowledge.value.state==='draft'&&!clues.value.length&&!knowledge.value.draft.clueIds?.length&&!knowledge.value.suggestion)
function figure(c:any){return s.p.value.annotations.find((a:any)=>a.characterId===c.id)}
function face(c:any){const a=figure(c);return c.draft.faceRegion||a?.faceRegion||a}
function add(){const rid=id();s.add('character',{name:'新人物',identity:'',biography:'',relationships:'',summary:'',evidence:'创作者命名，未提供历史身份经历',namingOrigin:'creator',roleType:'role',depictionScope:'unknown',visualHints:[],mentions:[],faceRegion:null},rid);s.add('knowledge',{characterId:rid,clueIds:[],reasons:{}},rid);selected.value=rid}
function acceptSuggestion(){if(knowledge.value?.suggestion){knowledge.value.draft=JSON.parse(JSON.stringify(knowledge.value.suggestion));knowledge.value.regenerated=true}}
watch(()=>s.focus.value,(v:string)=>{if(v.startsWith('character:')||v.startsWith('knowledge:')||v.startsWith('persona:'))selected.value=v.split(':')[1]},{immediate:true})
</script>
<template><div class="workspace-two"><aside class="entity-rail"><div class="rail-heading"><h2>人物档案</h2><button @click="add">＋ 人物</button></div><button v-for="c in people" :class="{selected:c.id===r?.id}" @click="s.selectEntity('character',c.id)"><div class="rail-avatar"><Portrait v-if="face(c)" :url="s.p.value.image" :box="face(c)"/><span v-else>人</span></div><span><b>{{c.draft.name}}</b><small>{{c.draft.identity||'未提供身份'}}</small><ReviewBadge :unit="s.unit('character:'+c.id)"/></span></button></aside><div v-if="r" class="entity-detail"><article :data-entity-key="'character:'+r.id"><fieldset :disabled="s.locked('character',r.id)"><div class="detail-title"><div><h2>{{r.draft.name}} <span v-if="r.draft.identity!==r.draft.name">{{r.draft.identity||'未提供身份'}}</span></h2><p>{{profile(r.draft)}}</p></div></div><details v-if="r.draft.creativeNaming"><summary>创作称谓依据</summary><p>原文称谓：{{r.draft.creativeNaming.sourceName}}。{{r.draft.creativeNaming.basis==='literature_interpretation'?'采用文献中的单一身份解释作创作称谓；原判断仍属推测。':'采用文献明确记载的身份称谓。'}}</p><p v-for="m in r.draft.creativeNaming.references"><q>{{m.quote}}</q><button v-if="m.documentId" @click="s.navigate('library','document:'+m.documentId+':'+m.page)">查看PDF原页</button></p></details><label class="profile-main">人物小传<textarea rows="6" :value="r.draft.summary||profile(r.draft)" @input="r.draft.summary=($event.target as HTMLTextAreaElement).value" placeholder="生成后自动填写，也可直接修改"/></label><details><summary>更多档案字段、头像与出处</summary><div class="profile-editor"><div><Portrait v-if="face(r)" :url="s.p.value.image" :box="face(r)"/><small>{{r.draft.faceRegion||figure(r)?.faceRegion?'面部截图（可校准）':'未确认面部，使用人物裁切'}}</small><button @click="showFace=!showFace">校准面部区域</button></div><div><label>姓名<input v-model="r.draft.name"></label><label>身份<input v-model="r.draft.identity"></label><label>经历<textarea v-model="r.draft.biography" placeholder="资料未提供时留空"/></label><label>人物简介<textarea v-model="r.draft.summary"/></label><label>人物关系<textarea v-model="r.draft.relationships"/></label><div class="compact-grid"><label>角色类型<select :value="r.draft.roleType||'unknown'" @change="r.draft.roleType=($event.target as HTMLSelectElement).value"><option value="unknown">未确定</option><option value="named">具名人物</option><option value="role">角色称谓</option><option value="group">群体角色</option></select></label><label>画中范围<select :value="r.draft.depictionScope||'unknown'" @change="r.draft.depictionScope=($event.target as HTMLSelectElement).value"><option value="unknown">未确定</option><option value="depicted">资料描述在画中</option><option value="background">仅背景或作者</option></select></label></div><details v-if="r.draft.visualHints?.length"><summary>查看原文身份提示</summary><div v-for="hint in r.draft.visualHints" class="identity-hint"><small>{{hint.text}} {{hint.exclusive?'（原文明示排他条件）':''}}</small><q>{{hint.quote}}</q><label v-if="hint.strength==='required'"><input type="checkbox" v-model="hint.constraintConfirmed">匹配必须满足此条件（遮挡或无法判断时保持未匹配）</label><small v-if="!hint.constraintConfirmed">自动提取的描述为匹配参考，明确冲突仍会被拦截。</small></div></details><label>依据与不确定性<textarea v-model="r.draft.evidence"/></label></div></div><RegionPicker v-if="showFace" :image="s.p.value.image" v-model="r.draft.faceRegion"/><details><summary>查看原文提及</summary><p v-for="m in r.draft.mentions"><small>{{m.documentId?'PDF 第'+m.page+'页':m.kind}} | 位置{{m.start}}–{{m.end}}</small><q>{{m.quote}}</q><button v-if="m.documentId" @click="s.navigate('library','document:'+m.documentId+':'+m.page)">查看PDF原页</button></p><p v-if="!r.draft.mentions?.length">未提供原文定位；不补编人物经历。</p></details><details v-if="structuredFacts.length"><summary>作品资料库中的人物依据（同一角色） · {{structuredFacts.length}} 条</summary><p v-for="f in structuredFacts" :key="f.id"><b>{{f.aspect}}</b> {{f.text}}<small>{{f.category==='inference'?'研究解释／推断':f.category==='supported'?'资料记载':'待核对'}} · {{f.referenceIds.length}} 处依据</small></p><button @click="s.navigate('library')">在统一作品资料库核对依据</button></details></details><ReviewUnit :unit-id="'character:'+r.id" label="确认此人物"/><button @click="s.remove(r)">删除人物</button></fieldset></article>
<article v-if="knowledge" :data-entity-key="'knowledge:'+r.id"><details><summary>知识范围与依据（自动分配，可调整）</summary><h2>人物知识</h2><p>资料、知识及角色设定共用一次确认；无需分别核对。</p><div v-if="!clues.length" class="empty">暂无线索，可先按身份交谈。</div><fieldset :disabled="s.locked('knowledge',r.id)"><div v-if="knowledge.suggestion" class="card"><h3>新的知识分配建议</h3><p v-for="cid in knowledge.suggestion.clueIds">{{s.rec('clue',cid)?.draft.name}}</p><button @click="acceptSuggestion">使用此建议</button></div><div class="card" v-for="cid in knowledge.draft.clueIds.filter((cid:string)=>!clues.some((c:any)=>c.id===cid))"><small>旧绑定已失效：{{s.rec('clue',cid)?.draft.name||cid}}</small><button @click="knowledge.draft.clueIds=knowledge.draft.clueIds.filter((id:string)=>id!==cid)">移除旧绑定</button></div><ClueGraph :key="r.id" v-model="knowledge.draft.clueIds" mode="knowledge" :folders="s.p.value.workspace.folders" :clues="s.entries('clue')" :eligible="clues.map((c:any)=>c.id)" :reasons="knowledge.draft.reasons" :disabled="s.locked('knowledge',r.id)"/><EntityActions v-if="!knowledgeWaiting" :record="knowledge"/></fieldset></details></article><PersonaEditor v-if="s.rec('persona',r.id)" :key="r.id" :character-id="r.id"/></div><article v-else><div class="empty">先在古画资料库整理人物，或手动添加人物。</div></article></div></template>
